# Applies the fixes to store.py, tigergraph_client.py and investigator.py. Safe to run twice.
from pathlib import Path
def block(s, a, b):
    i = s.index(a); j = s.index(b, i); return i, j
RAW = 'def _build_from_raw(raw_dir: Path) -> pd.DataFrame:\n    core_cols = ["TransactionID", "TransactionDT", "TransactionAmt", "ProductCD", "card2", "card3",\n                 "card4", "card5", "card6", "customer_id", "ts", "channel", "risk_score", "addr1",\n                 "addr2", "dist1", "dist2", "P_emaildomain", "R_emaildomain"] + SIG_COLS\n    card_cols = ["card2", "card3", "card4", "card5", "card6"]\n    parts = []\n    for ch in pd.read_csv(raw_dir / "transactions.csv", usecols=core_cols, chunksize=100_000,\n                          dtype={"TransactionID": str, "addr1": str, "addr2": str,\n                                 **{c: str for c in card_cols}}):\n        parts.append(ch)\n    df = pd.concat(parts, ignore_index=True)\n    # Card numbering used by the case pack (validated against its card_ids): card2..card6\n    # as the CSV text (missing -> "", trailing ".0" dropped), distinct tuples per customer\n    # sorted as strings, numbered K1, K2, ... in that order.\n    for c in card_cols:\n        df[c] = (df[c].astype(object).where(df[c].notna(), "").astype(str).str.strip()\n                 .str.replace(r"\\.0$", "", regex=True))\n    use = ["customer_id"] + card_cols\n    cards = df[use].drop_duplicates().sort_values(use).reset_index(drop=True)\n    cards["k"] = cards.groupby("customer_id").cumcount() + 1\n    df = df.merge(cards, on=use, how="left", validate="many_to_one")\n    df["card_id"] = df.customer_id + "-K" + df.k.astype(str)\n    idt = pd.read_csv(raw_dir / "identity.csv", dtype={"TransactionID": str},\n                      usecols=["TransactionID", "id_15", "id_23", "id_30", "id_31", "id_33", "id_34",\n                               "DeviceType", "DeviceInfo"])\n    idt["device_profile_id"] = idt.apply(_device_key, axis=1).replace("", np.nan)\n    df = df.merge(idt[["TransactionID", "device_profile_id"] + ID_COLS], on="TransactionID", how="left")\n    df["has_device_record"] = df.device_profile_id.notna()\n    return df.drop(columns=["k"] + card_cols)\n\n\n'
CHK = 'def _check_ids(df: pd.DataFrame) -> None:\n    """Card/customer IDs must match the case pack and closed cases, or every answer is wrong."""\n    by_id = df.set_index("TransactionID")[["card_id", "customer_id"]]\n    cp = pd.read_csv(config.DATA_DIR / "case_pack.csv", dtype=str)\n    cc = pd.read_csv(config.DATA_DIR / "closed_cases_history.csv", dtype=str,\n                     usecols=["card_id", "first_fraud_txn_id"]).dropna()\n    bad = []\n    for tid, card in list(zip(cp.flagged_txn_id, cp.card_id)) + list(zip(cc.first_fraud_txn_id, cc.card_id)):\n        if tid not in by_id.index or by_id.at[tid, "card_id"] != card:\n            bad.append((tid, card, by_id.at[tid, "card_id"] if tid in by_id.index else None))\n    n = len(cp) + len(cc)\n    if bad:\n        raise ValueError(f"card_id mismatch on {len(bad)}/{n} case-pack/closed-case transactions, "\n                         f"e.g. {bad[:3]} (txn, expected, built)")\n    log.info("ID check: all %d case-pack/closed-case card_ids match the store", n)\n\n\n'
CONN = '    def connect(self) -> bool:\n        """Establish connection to TigerGraph."""\n        if not self.host:\n            logger.warning("No TigerGraph host configured")\n            return False\n\n        import pyTigerGraph as tg\n        user = os.getenv("TIGERGRAPH_USER") or os.getenv("TG_USERNAME", "tigergraph")\n        password = os.getenv("TIGERGRAPH_SECRET") or os.getenv("TG_PASSWORD", "tigergraph")\n        attempts = []\n        cloud = "tgcloud.io" in self.host or os.getenv("TIGERGRAPH_USE_SAVANNA", "").lower() == "true"\n        if self.token:  # Savanna API token\n            attempts.append(("api token", dict(apiToken=self.token)))\n        if os.getenv("TIGERGRAPH_SECRET"):  # a GSQL secret is exchanged for a REST token\n            attempts.append(("gsql secret", dict(gsqlSecret=os.environ["TIGERGRAPH_SECRET"], username=user,\n                                                 password=password)))\n        if self.token:  # some Savanna "API tokens" are really secrets: exchange them for a REST token\n            attempts.append(("api token as secret", dict(gsqlSecret=self.token, username=user, password=password)))\n        attempts.append(("user/password", dict(username=user, password=password)))\n        for label, kw in attempts:\n            try:\n                self.conn = tg.TigerGraphConnection(host=self.host, graphname=self.graph, tgCloud=cloud, **kw)\n                if label in ("gsql secret", "api token as secret"):\n                    self.conn.getToken(kw["gsqlSecret"])\n                # /echo accepts any token, so verify with an authenticated RESTPP call.\n                self.conn.getVertexCount("*")\n                self._connected = True\n                logger.info("Connected to TigerGraph at %s (%s)", self.host, label)\n                return True\n            except Exception as e:  # noqa: BLE001\n                logger.warning("TigerGraph connection via %s failed: %s", label, str(e)[:200])\n        return False\n\n'
UP = '    def _schema(self) -> tuple[dict, set]:\n        """Live vertex attributes per type and edge type names (the deployed schema can differ\n        from tigergraph/schema.gsql, e.g. an older InvestigationCase definition)."""\n        if getattr(self, "_schema_cache", None) is None:\n            vt = {}\n            for t in self.conn.getVertexTypes():\n                try:\n                    vt[t] = {a["AttributeName"] for a in self.conn.getVertexType(t).get("Attributes", [])}\n                except Exception:  # noqa: BLE001\n                    vt[t] = set()\n            self._schema_cache = (vt, set(self.conn.getEdgeTypes()))\n        return self._schema_cache\n\n    def upsert_agent_case(self, rec: dict) -> bool:\n        """Write an engine case (src/engine) as an InvestigationCase vertex with edges.\n\n        Only attributes/edges that exist in the deployed schema are sent. Returns True only\n        when the vertex can be read back; written_to_graph is taken from this value."""\n        if not self._connected and not self.connect():\n            return False\n        try:\n            vtypes, etypes = self._schema()\n            if "InvestigationCase" not in vtypes:\n                logger.warning("upsert_agent_case: no InvestigationCase vertex type in the live schema")\n                return False\n            status = ("closed_fraud" if rec["verdict"] == "fraud" else\n                      "closed_legitimate" if rec["verdict"] == "legitimate" else "open")\n            props = {"customer_id": rec["customer_id"], "card_id": (rec["cards"] or [""])[0],\n                     "opened_at": rec["opened_at"], "verdict": rec["verdict"], "pattern": rec["pattern"],\n                     "status": status, "fraud_probability": rec.get("p"), "exposure_usd": rec.get("exposure")}\n            allowed = vtypes["InvestigationCase"]\n            props = {k: v for k, v in props.items() if v is not None and (not allowed or k in allowed)}\n            cid = rec["graph_case_id"]\n            self.upsert_vertex("InvestigationCase", cid, props)\n            links = [("CASE_INVOLVES_TXN", "Transaction", rec.get("txn_ids") or []),\n                     ("CASE_ON_CARD", "Card", rec.get("cards") or []),\n                     ("CASE_INVOLVES_DEVICE", "DeviceProfile", rec.get("devices") or [])]\n            n_ok = n_fail = 0\n            for et, tt, ids in links:\n                if et not in etypes:\n                    continue\n                for tid in ids:\n                    try:\n                        self.upsert_edge("InvestigationCase", cid, et, tt, str(tid))\n                        n_ok += 1\n                    except Exception as e:  # noqa: BLE001\n                        n_fail += 1\n                        logger.debug("edge %s -> %s failed: %s", et, tid, e)\n            ok = self.get_vertex("InvestigationCase", cid) is not None\n            logger.info("TigerGraph: %s written=%s (%d attrs, %d edges, %d edge failures)",\n                        cid, ok, len(props), n_ok, n_fail)\n            return ok\n        except Exception as e:  # noqa: BLE001\n            logger.warning("upsert_agent_case failed: %s", e)\n            return False\n\n'
p = Path("src/engine/store.py"); s = p.read_text(encoding="utf-8")
i, j = block(s, "def _build_from_raw", "def _build_from_prepared"); s = s[:i] + RAW + s[j:]
if "def _check_ids" not in s:
    s = s.replace("    df.to_parquet(out)\n", "    _check_ids(df)\n    df.to_parquet(out)\n", 1)
    i, _ = block(s, "def load_closed_cases", "def load_closed_cases"); s = s[:i] + CHK + s[i:]
p.write_text(s, encoding="utf-8"); print("store.py patched")
p = Path("src/graph/tigergraph_client.py"); s = p.read_text(encoding="utf-8")
i, j = block(s, "    def connect(self) -> bool:", "    def is_connected"); s = s[:i] + CONN + s[j:]
a = "    def _schema(self)" if "    def _schema(self)" in s else "    def upsert_agent_case"
i, j = block(s, a, "    def _run_interpret_or_rest"); s = s[:i] + UP + s[j:]
p.write_text(s, encoding="utf-8"); print("tigergraph_client.py patched")
p = Path("src/engine/investigator.py"); s = p.read_text(encoding="utf-8")
old = '"txn_ids": list(aff.TransactionID), "opened_at": str(as_of)}'
if old in s:
    s = s.replace(old, '"txn_ids": list(aff.TransactionID), "opened_at": str(as_of),\n               "p": round(float(p1), 4), "exposure": exposure}')
    p.write_text(s, encoding="utf-8")
print("investigator.py patched")